function clientHref(label: string) {
  const value = label.toLowerCase();
  if (value.includes("notification preference")) return "/client/settings/notifications";
  if (value.includes("notification")) return "/client/notifications";
  if (value.includes("organization") || value.includes("billing detail") || value.includes("portal preference")) return "/client/settings/organization";
  if (value.includes("user") || value.includes("team access") || value.includes("invitation")) return "/client/settings/users";
  if (value.includes("contract") || value.includes("agreement") || value.includes("proposal")) return "/client/contracts/con-2024-0578";
  if (value.includes("invoice") || value.includes("payment") || value.includes("billing")) return "/client/billing/inv-2024-0882";
  if (value.includes("approval") || value.includes("approve") || value.includes("review")) return "/client/approvals";
  if (value.includes("distribution")) return "/client/distribution";
  if (value.includes("publish") || value.includes("live link") || value.includes("magazine")) return "/client/publishing/ceo-spotlight-may-2024";
  if (value.includes("report") || value.includes("download")) return "/client/reports";
  if (value.includes("renew") || value.includes("continuation") || value.includes("option")) return "/client/renewals";
  if (value.includes("support") || value.includes("question") || value.includes("help")) return "/client/support";
  if (value.includes("media") || value.includes("podcast") || value.includes("video") || value.includes("recording")) return "/client/media/ceo-spotlight-michael-chen";
  if (value.includes("meeting") || value.includes("calendar") || value.includes("call")) return "/client/meetings";
  if (value.includes("message")) return "/client/messages/editorial-draft-review";
  if (value.includes("file") || value.includes("asset") || value.includes("upload")) return "/client/assets";
  if (value.includes("activity") || value.includes("history")) return "/client/activity";
  if (value.includes("project")) return "/client/projects";
  return "/client";
}

function Button({ children, primary, danger, href }: { children: React.ReactNode; primary?: boolean; danger?: boolean; href?: string }) {
  const cls = `${s.button} ${primary ? s.primary : ""} ${danger ? s.danger : ""}`;
  return href ? <Link className={cls} href={href}>{children}</Link> : <button className={cls} type="button">{children}</button>;
}
function Pill({ children, tone = "violet" }: { children: React.ReactNode; tone?: Tone }) { return <span className={`${s.pill} ${s[`pill_${tone}`]}`}>{children}</span>; }
function IconBox({ I, tone = 0 }: { I: Icon; tone?: number }) { return <span className={`${s.iconBox} ${s[`tone${tone % 7}`]}`}><I size={18} /></span>; }
function Person({ name = "Sarah Johnson", role = "Account Manager", src = sarah }: { name?: string; role?: string; src?: string }) { return <span className={s.person}><Image alt="" height={30} src={src} width={30} /><span><b>{name}</b><small>{role}</small></span></span>; }
function Cover({ wide = false }: { wide?: boolean }) { return <div className={`${s.cover} ${wide ? s.wideCover : ""}`}><Image alt="The Visionary Leader" fill sizes="140px" src={arjun}/><span>VISION</span><b>THE VISIONARY<br/>LEADER</b></div>; }
function Panel({ title, action, children, className="" }: { title: string; action?: string; children: React.ReactNode; className?: string }) { return <section className={`${s.panel} ${className}`}><header><h2>{title}</h2>{action&&<Link href={clientHref(`${title} ${action}`)}>{action}<ArrowRight size={12}/></Link>}</header>{children}</section>; }
function SearchBox({ text }: { text: string }) { return <label className={s.search}><Search size={15}/><input aria-label={text} placeholder={text}/></label>; }
function PageHead({ title, subtitle, action }: { title: string; subtitle: string; action?: React.ReactNode }) { return <div className={s.pageHead}><div><h1>{title}</h1><p>{subtitle}</p></div><aside>{action??<Button href="/client/messages"><MessageSquare size={14}/> Send Message</Button>}</aside></div>; }
function Stats({ items }: { items: Array<[string,string,Icon,Tone?]> }) { return <div className={s.stats}>{items.map(([a,b,I],i)=><article key={a}><IconBox I={I} tone={i}/><span><small>{a}</small><b>{b}</b></span></article>)}</div>; }
function Filters({ items, search="Search…" }: { items: string[]; search?: string }) { return <div className={s.filters}>{items.map(x=><button key={x}>{x}<ChevronDown size={12}/></button>)}<SearchBox text={search}/><div className={s.viewButtons}><button><List size={14}/></button><button><FolderKanban size={14}/></button></div></div>; }
function Tabs({ items, active=0 }: { items: string[]; active?: number }) { return <nav className={s.tabs}>{items.map((x,i)=><button className={i===active?s.activeTab:""} key={x}>{x}</button>)}</nav>; }
function Facts({ items }: { items: Array<[string,string]> }) { return <dl className={s.facts}>{items.map(x=><div key={x[0]}><dt>{x[0]}</dt><dd>{x[1]}</dd></div>)}</dl>; }
function MiniRows({ rows }: { rows: Array<[string,string,string?,Icon?]> }) { return <div className={s.miniRows}>{rows.map(([a,b,c,I=FileText],i)=><div key={a}><IconBox I={I} tone={i}/><p><b>{a}</b><small>{b}</small></p>{c&&<Link className={s.rowAction} href={clientHref(`${a} ${c}`)}>{c}</Link>}</div>)}</div>; }
function Table({ headers, rows, selected=0, template }: { headers:string[]; rows:React.ReactNode[][]; selected?:number; template:string }) { return <div className={s.tableWrap} style={{"--cols":template} as React.CSSProperties}><div className={s.tableHead}>{headers.map(x=><span key={x}>{x}</span>)}</div>{rows.map((row,i)=><article className={i===selected?s.selectedRow:""} key={i}>{row.map((cell,j)=><span key={j}>{cell}</span>)}</article>)}<footer>Showing 1 to {rows.length} of {Math.max(rows.length,28)} items <span>‹ <b>1</b> 2 3 ··· 6 ›</span><select><option>10 / page</option></select></footer></div>; }
function Actions({ items }: { items:Array<[string,Icon]> }) { return <div className={s.actionList}>{items.map(([x,I])=><Link href={clientHref(x)} key={x}><I size={14}/><span>{x}</span><ArrowRight size={12}/></Link>)}</div>; }
function Toggle({ on=true }: { on?:boolean }) { return <i className={`${s.toggle} ${on?s.toggleOn:""}`}><b/></i>; }

